import{_ as a,o as t,c as n,ao as i}from"./chunks/framework.BXdo0ND6.js";const g=JSON.parse('{"title":"Diagnostics and operation failures","description":"","frontmatter":{},"headers":[],"relativePath":"implementation/diagnostics.md","filePath":"implementation/diagnostics.md","lastUpdated":null}'),s={name:"implementation/diagnostics.md"};function o(r,e,c,l,d,p){return t(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="Diagnostics-and-operation-failures" tabindex="-1">Diagnostics and operation failures <a class="header-anchor" href="#Diagnostics-and-operation-failures" aria-label="Permalink to &quot;Diagnostics and operation failures {#Diagnostics-and-operation-failures}&quot;">​</a></h1><p>High-level readers, filters, temporal updates, and writers use scoped VTK diagnostics. Each operation has a fresh collector attached to its target algorithm; no messages are stored in a process-global buffer.</p><h2 id="Severity-and-status" tabindex="-1">Severity and status <a class="header-anchor" href="#Severity-and-status" aria-label="Permalink to &quot;Severity and status {#Severity-and-status}&quot;">​</a></h2><ul><li><p>VTK errors and unsuccessful native return statuses throw <code>VTKError</code>.</p></li><li><p>Warnings do not make a successful operation fail. They are reported as warnings and remain available in the diagnostic-returning API.</p></li><li><p>Normal text and debug messages are nonfatal diagnostic records.</p></li><li><p>A null required output is an error. A valid dataset with zero points or cells is a successful empty result.</p></li></ul><p><code>VTKError</code> and <code>VTKDiagnostic</code> retain the operation, algorithm class, optional filename, native status, message, and severity. This makes reader and writer failures identifiable without parsing a combined output-window string.</p><h2 id="Scope,-nesting,-and-concurrency" tabindex="-1">Scope, nesting, and concurrency <a class="header-anchor" href="#Scope,-nesting,-and-concurrency" aria-label="Permalink to &quot;Scope, nesting, and concurrency {#Scope,-nesting,-and-concurrency}&quot;">​</a></h2><p>A collector lives only for the duration of its native operation. Observers are removed on success and exceptional exits, so messages cannot leak into the next call. Nested operations have nested diagnostic scopes. Independent algorithms can execute concurrently without a global diagnostics lock; collectors synchronize their own callbacks.</p><p>As with VTK itself, concurrently updating or mutating the <strong>same</strong> algorithm is unsupported. Pipeline outputs may keep their VTK object alive, but retaining an algorithm and updating it again can still mutate earlier output contents.</p><p>The generated raw API remains raw: calls such as <code>Update</code> do not implicitly become Julia checked operations. Use the high-level facade when typed errors, warning separation, and contextual diagnostics are required.</p>',9)])])}const h=a(s,[["render",o]]);export{g as __pageData,h as default};
